    static constexpr float LOST_GAP = 6.0f;

    static int sfxSelect(int type) { return units::selectSoundId(type); }
    static int sfxAlarm(int type)
    {
        int id = units::orderSoundId(type);
        return id > 0 ? id + 1 : 0;
    }
    static int sfxOrder(int type)  { return units::orderSoundId(type); }

    // Sea life, alive rather than pinned where the map left it. The strips are
    // directional the same way the crab is in STCrabC::SetSprRange, which walks
    // frames [dir*6, dir*6+5]: eight headings, count/8 frames each. Every
    // NATURE strip divides by eight - crab, medusa and langusta at 6 frames a
    // heading, octopus 9, scat 15, zmej 20, shark 30.
    static const int FISH_DIRS = 8;
    struct Fish {
        uint32_t kind = 0;
        float x = 0, y = 0, tx = 0, ty = 0;
        // Poziom plywania, **bezwzgledny**, tak samo jak `Unit::z`. Rekord
        // mapy podaje go pod +28 i `STSharkC::CreateShark` odrzuca `4 < z`,
        // czyli to te same piec poziomow. Rysowane dotad zawsze na dnie:
        // przez to 40% stworzen na mapie siedzialo nizej, niz mialo.
        float z = 0;
        float speed = 1.0f;
        int dir = 0;
        float anim = 0;
        uint32_t rnd = 1;
    };
    std::vector<Fish> fish;

    // Wulkan (`STVolcanoC`, rekord mapy typu 230). Nie jest dekoracja: ma
    // wlasna maszyne stanow w `STVolcanoC::GetMessage` i trzy paski w
    // archiwum TERENU, nie w OTHER - `expl_vol` krater (46 klatek),
    // `expl_vob` babelki (15) i `expl_vop` wyrzut (31).
    //
    // Cykl jest odczytany, nie wymyslony:
    //   * klatka idzie co TRZECI tik (`tick % 3 == 0`), czyli 25/3 na sekunde,
    //   * w spoczynku krater chodzi po klatkach 0..10 (`+0x75 = 10`),
    //   * wybuch ustawia klatke na 10 i granice na 41 (`+0x71 = 10`,
    //     `+0x75 = 0x29`) oraz wyrzut 0..31 (`+0x82 = 0x1f`, dokladnie tyle,
    //     ile ma klatek `expl_vop`),
    //   * nastepny wybuch wypada za `(rnd >> 16) % 0x2711 + 20000` tikow,
    //     czyli **20000..30000 tikow = 800..1200 s** przy 25 tikach,
    //   * start gra dzwiek 1206 (`othe_002`), koniec 1205 (`othe_001`).
    struct Volc {
        float x = 0, y = 0;
        int   z = 0;
        float body = 0;                 // klatka krateru, ulamkowo
        float bub  = 0;                  // klatka babelkow
        float plume = 0;                 // klatka wyrzutu
        bool  erupt = false;
        float left = 0;                  // sekundy do nastepnego wybuchu
        uint32_t rnd = 1;
    };
    std::vector<Volc> volcs;

