        uint32_t kind = 0;                      // 221 korium, 222 metal, 220 zloto
        int   aniState = 0;                     // 0 nic, 1 luk w gore, 2 surowiec,
                                                // 3 luk w dol - tak jak w TLO_rc.cpp
        float aniStep = 0;
