    static bool IsAirRig(int tobj)  { return tobj == 80; }   // Air Extractor / O2 Sublimator
    static bool IsEnergyRig(int tobj) { return tobj == 97; }  // SI Energy Accumulator
    static bool IsReplenishPod(int tobj) { return tobj == 98; }
