    // Ikona wezla w drzewie: `HLP_UPG_<NN>` ma dokladnie 26x14.
    static const int TREE_ICON_W = 26, TREE_ICON_H = 14;

    // Okno badan, wymiary zmierzone w `BKG_RESEARCHW_<rasa>` (317x100):
    // belka tytulu x 64..254 y 3..12, pasek gniazd x 32..285 y 19..44.
    // Gniazdo to dokladnie ikona `UPG_<NN>` - 50x26, piec w rzedzie.
    static const int RES_SLOTS = 5;
    static const int RES_SLOT_X = 32, RES_SLOT_Y = 19;
    static const int RES_SLOT_W = 50, RES_SLOT_H = 26;
    static const int RES_TITLE_X = 66, RES_TITLE_Y = 2;
    // Ponizej paska sa dwa pola 46x16 (x 112 i 161, y 52), a na dole rzad
    // przyciskow: strzalka x 104..122, ZAMKNIJ x 133..183, strzalka
    // x 196..214, wszystkie y 79..94.
    static const int RES_BOX_Y = 52, RES_BOX_W = 46, RES_BOX_H = 16;
    static const int RES_BOX1_X = 112, RES_BOX2_X = 161;
    static const int RES_BUT_Y = 79, RES_BUT_H = 16;
    static const int RES_PREV_X = 104, RES_ARROW_W = 19;
    static const int RES_CLOSE_X = 133, RES_CLOSE_W = 51;
    static const int RES_NEXT_X = 196;

    static RECT ResRect(const RECT &w, int x, int y, int cw, int ch)
    {
        RECT r;
        r.left = w.left + x;
        r.top = w.top + y;
        r.right = r.left + cw;
        r.bottom = r.top + ch;
        return r;
    }

    bool ResearchSlot(const RECT &w, int k, RECT &r) const
    {
        if (k < 0 || k >= RES_SLOTS) return false;
        r.left = w.left + RES_SLOT_X + k * RES_SLOT_W;
        r.top = w.top + RES_SLOT_Y;
        r.right = r.left + RES_SLOT_W;
        r.bottom = r.top + RES_SLOT_H;
        return true;
    }

    // Numer pozycji na liscie dostepnych badan pod kursorem; -1 gdy zadna.
    int ResearchSlotAt(int px, int py)
    {
        if (winOpen != WIN_RESEARCH) return -1;
        RECT w;
        if (!WinRect(WIN_RESEARCH, w)) return -1;
        for (int k = 0; k < RES_SLOTS; ++k) {
            RECT r;
            if (!ResearchSlot(w, k, r)) break;
            if (px >= r.left && px < r.right && py >= r.top && py < r.bottom) {
                int i = TechOpen(winPage * RES_SLOTS + k);
                if (i < 0) return -1;
                return winPage * RES_SLOTS + k;
            }
        }
        return -1;
    }

    // Czy stac nas na te technologie. Silikony placa energia, ale to ten sam
    // licznik co zloto.
    bool Afford(int i) const
    {
        int n = 0;
        const tech::Tech *t = tech::list(n);
        return i >= 0 && i < n && Me().bank.gold >= t[i].gold;
    }

    // Drzewo technologii ma tlo jako PASEK typu 6 (`BKG_HLPTTREE_0..2`),
    // a nie DIB jak reszta okien, wiec idzie osobna sciezka. Kanwa paska ma
    // 412x295, ale sama grafika to 332x270 (WS), 366x253 (BO) i 366x341 (SI).
    const spr::Frame *WinBkgStrip(int id)
    {
        if (id != WIN_TTREE || !unitSet.ok()) return nullptr;
        char rec[32];
        std::snprintf(rec, sizeof(rec), "BKG_HLPTTREE_%d", PlayerSide());
        const spr::Strip *st = hud.strip(rec);
        if (!st || st->count() == 0) {
            std::snprintf(rec, sizeof(rec), "BKG_HLPTTREE_0");
            st = hud.strip(rec);
        }
        return st && st->count() ? st->at(0) : nullptr;
    }

    const panel::Image *WinBkg(int id)
    {
        if (id <= WIN_NONE || id >= WIN_COUNT || !hud.ok()) return nullptr;
        if (!WinDefs()[id].bkg) return nullptr;
        char rec[64];
        const char *f = WinDefs()[id].bkg;
        // Czesc tel nie ma wariantu na rase - BKG_SETANYW i BKG_HLPTTREE_<n>.
        if (std::strstr(f, "%s")) std::snprintf(rec, sizeof(rec), f, hudRace);
        else                      std::snprintf(rec, sizeof(rec), "%s", f);
        const panel::Image *im = hud.image(rec);
        return im && im->ok() ? im : nullptr;
    }

    // Okno stoi na srodku pola mapy, nad dolnym paskiem.
    bool WinRect(int id, RECT &r)
    {
        int iw = 0, ih = 0;
        if (const panel::Image *im = WinBkg(id)) { iw = im->w; ih = im->h; }
        else if (const spr::Frame *f = WinBkgStrip(id)) { iw = f->w; ih = f->h; }
        else return false;
        // Drzewo technologii ma wezly WYCHODZACE poza samo tlo: gra rysuje
        // je na powierzchni 412 px szerokiej i przewija w pionie, a tlo to
        // tylko siatka polaczen. Okno musi wiec objac wszystkie wezly.
        if (id == WIN_TTREE) {
            int n = 0;
            const tech::Tech *t = tech::list(n);
            for (int i = 0; i < n; ++i) {
                if (t[i].side != PlayerSide()) continue;
                if (t[i].x + TREE_ICON_W > iw) iw = t[i].x + TREE_ICON_W;
                if (t[i].y + TREE_ICON_H > ih) ih = t[i].y + TREE_ICON_H;
            }
        }
        RECT vp = Viewport();
        int bottom = vp.bottom;
        BarLay L;
        if (BarLayout(&L)) bottom = L.y;
        r.left = vp.left + (vp.right - vp.left - iw) / 2;
        r.top = vp.top + (bottom - vp.top - ih) / 2;
        if (r.top < vp.top + 4) r.top = vp.top + 4;
        r.right = r.left + iw;
        r.bottom = r.top + ih;
        return true;
    }

    // Klawisz `E` otwiera okno badan **jak przycisk w budynku**: jesli
    // zaznaczone jest laboratorium, pokazuje jego rodzine; jesli nie -
    // wszystko, co gracz ma czym zbadac. Bez zadnego budynku badawczego
    // okno sie nie otwiera, bo nie byloby na czym badac.
    Bld *SelBld()
    {
        if (!sel.empty()) return nullptr;       // lodz ma pierwszenstwo
        if (selBld.empty() || selBld[0] < 0 || selBld[0] >= int(blds.size()))
            return nullptr;
        return &blds[size_t(selBld[0])];
    }

    // Rzad szesciu priorytetow tlenu: ikony `BUT_PRIORITY_<rasa>_<NN>`
    // maja 17x10.
    bool BldPrioRect(const RECT &w, int k, RECT &r)
    {
        if (k < 0 || k >= BLD_PRIOS) return false;
        RECT b = WinBody(WIN_BEHAV, w);
        r.left = b.left + 6 + k * 20;
        r.top = b.top + 2 * (font.height() + 3);
        r.right = r.left + 17;
        r.bottom = r.top + 10;
        return r.right <= b.right && r.bottom <= b.bottom;
    }

    int BldPrioAt(int px, int py)
    {
        if (winOpen != WIN_BEHAV) return -1;
        RECT w;
        if (!WinRect(WIN_BEHAV, w)) return -1;
        for (int k = 0; k < BLD_PRIOS; ++k) {
            RECT r;
            if (!BldPrioRect(w, k, r)) break;
            if (px >= r.left && px < r.right && py >= r.top && py < r.bottom)
                return k;
        }
        return -1;
    }

    // Rzad progow naprawy w oknie zachowania: cztery gniazda 51x16.
    bool BehRepairRect(const RECT &w, int k, RECT &r)
    {
        if (k < 0 || k >= BEH_REPAIRS) return false;
        RECT b = WinBody(WIN_BEHAV, w);
        int cw = int(b.right - b.left) / BEH_REPAIRS;
        r.left = b.left + k * cw;
        r.top = b.top + 4 * (font.height() + 3);
        r.right = r.left + (cw > 53 ? 51 : cw - 2);
        r.bottom = r.top + 16;
        return r.bottom <= b.bottom;
    }

    int BehRepairAt(int px, int py)
    {
        if (winOpen != WIN_BEHAV) return -1;
        RECT w;
        if (!WinRect(WIN_BEHAV, w)) return -1;
        for (int k = 0; k < BEH_REPAIRS; ++k) {
            RECT r;
            if (!BehRepairRect(w, k, r)) break;
            if (px >= r.left && px < r.right && py >= r.top && py < r.bottom)
                return k;
        }
        return -1;
    }

    void OpenResearch()
    {
        int lab = -1;
        if (!selBld.empty() && selBld[0] >= 0 && selBld[0] < int(blds.size())) {
            const Bld &b = blds[size_t(selBld[0])];
            if ((b.owner & 7) == uint32_t(me & 7) && b.buildLeft <= 0
                && IsResearchBld(int(b.tobj), PlayerSide())) lab = selBld[0];
        }
        if (lab < 0 && !HasResearchBld(uint32_t(me))) {
            Say(PlayerSide() == 2 ? "brak modulu Command Huba"
                                  : "brak centrum badan");
            return;
        }
        OpenResearchFor(lab);
    }

    void OpenResearchFor(int lab)
    {
        if(lab>=0 && (lab>=int(blds.size()) || blds[size_t(lab)].hp<=0
            || (blds[size_t(lab)].owner&7)!=uint32_t(me&7)
            || !BldControlCompatible(blds[size_t(lab)]) || !BldCompatible(blds[size_t(lab)]))) return;
        // Selecting another laboratory changes this window's owner instead
        // of treating it as a second click on the same window's toggle.
        bool replace = winOpen == WIN_RESEARCH && researchBld != lab;
        if (replace) winOpen = WIN_NONE;
        researchBld = lab;
        OpenWin(WIN_RESEARCH);
    }

    // **Przycisk ZAMKNIJ jest wrysowany w tlo okna** - blok 51x16 w barwie
    // rasy, w dolnym pasie. Zamiast wpisywac wspolrzedne dla kazdego okna
    // i kazdej rasy, szukamy go w samej grafice: w dolnych trzydziestu
    // wierszach ciagu nasyconych pikseli dlugosci 45..60.
    //
    // Wychodzi z tego (szerokosc-95, wysokosc-21) dla okien-dialogow
    // i srodek dla okien `ProdPanelTy` - ale reguly nie trzeba znac,
    // bo mierzymy.
    struct CloseBox { int win, race; RECT r; bool ok; };
    std::vector<CloseBox> closeCache;

    static bool SatPix(uint32_t c)
    {
        int r = int((c >> 16) & 0xff), g = int((c >> 8) & 0xff), b = int(c & 0xff);
        int hi = r > g ? (r > b ? r : b) : (g > b ? g : b);
        int lo = r < g ? (r < b ? r : b) : (g < b ? g : b);
        return hi - lo > 40 && (r + g + b) / 3 > 50;
    }

    bool WinCloseRect(int id, RECT &out)
    {
        int race = hudRace[0] * 256 + hudRace[1];
        for (const CloseBox &c : closeCache)
            if (c.win == id && c.race == race) {
                if (!c.ok) return false;
                RECT w;
                if (!WinRect(id, w)) return false;
                out.left = w.left + c.r.left;
                out.top = w.top + c.r.top;
                out.right = w.left + c.r.right;
                out.bottom = w.top + c.r.bottom;
                return true;
            }
        CloseBox nc = { id, race, RECT{ 0, 0, 0, 0 }, false };
        const panel::Image *im = WinBkg(id);
        if (im && im->ok()) {
            for (int y = im->h - 30; y < im->h && !nc.ok; ++y) {
                if (y < 0) continue;
                int x = 0;
                while (x < im->w) {
                    if (SatPix(hud.palette()[im->idx[size_t(y * im->w + x)]])) {
                        int s = x;
                        while (x < im->w
                               && SatPix(hud.palette()[im->idx[size_t(y * im->w + x)]]))
                            ++x;
                        if (x - s >= 45 && x - s <= 60) {
                            nc.r.left = s;  nc.r.right = x;
                            nc.r.top = y;   nc.r.bottom = y + 16;
                            nc.ok = true;
                            break;
                        }
                    } else ++x;
                }
            }
        }
        closeCache.push_back(nc);
        return WinCloseRect(id, out);
    }

    // Okna bez wrysowanego przycisku (`BKG_SETANYW`, `BKG_OPT_*`, drzewo)
    // dostaja swoj w prawym dolnym rogu, zeby dalo sie je zamknac tak samo.
    // **Przycisk ZAMKNIJ tez jest w exe.** Szukanie go w grafice (ciag
    // nasyconych pikseli w dolnych trzydziestu wierszach) dziala, ale to
    // heurystyka - a `SpecPanelTy::InitPanel` dostaje jego rog wprost,
    // w dwoch ostatnich argumentach. Rozmiar to `BUT_MEDIUM`, 51x16.
    //
    // Rynek ma przy tym **wariant rasowy** w znanym ksztalcie
    // `(-(g_byGameMode != 3) & MASKA) + BAZA`: Silikony 222, ludzie 216.
    struct CloseDef { int win; int x, y, xSi; };
    static const CloseDef *CloseDefs(int &n)
    {
        static const CloseDef k[] = {
            { WIN_BEHAV,   153, 119, 153 },
            { WIN_FORM,    201, 119, 201 },
            { WIN_INFOC,   216, 139, 216 },
            { WIN_TRADE,   216, 119, 222 },
            { WIN_UPGRADE, 201, 119, 201 },
            { WIN_SETANY,  201, 119, 201 },
            { WIN_DIPLO,   369, 199, 369 },
        };
        n = int(sizeof(k) / sizeof(k[0]));
        return k;
    }

    bool CloseFromExe(int id, const RECT &w, RECT &out) const
    {
        int n = 0;
        const CloseDef *k = CloseDefs(n);
        for (int i = 0; i < n; ++i) {
            if (k[i].win != id) continue;
            int x = PlayerSide() == 2 ? k[i].xSi : k[i].x;
            out = RECT{ w.left + x, w.top + k[i].y,
                        w.left + x + 51, w.top + k[i].y + 16 };
            return true;
        }
        return false;
    }

    bool CloseButton(int id, RECT &out)
    {
        if (id == WIN_CHAT) return false; // one-line input strip; Escape closes it
        RECT wr;
        if (WinRect(id, wr) && CloseFromExe(id, wr, out)) return true;
        if (WinCloseRect(id, out)) return true;
        RECT w;
        if (!WinRect(id, w)) return false;
        out.right = w.right - 6;
        out.left = out.right - 51;
        out.bottom = w.bottom - 5;
        out.top = out.bottom - 16;
        return true;
    }

    // ---------------------------- okno ustawien -------------------------
    //
    // `OptPanelTy` ma cztery zakladki; ich napisy siedza w `st_string.dll`
    // pod 16000 GLOWNE, 16007 USTAWIENIA, 16020 ASYSTENCI, 16009 CELE,
    // a zawartosc zakladki GLOWNE pod 16001..16005 i 16022.
    //
    // Pole tresci zmierzone w `BKG_OPTIONS_<rasa>`: x 5..290, y 19..143.
    int optTab = 0;
    bool shadowsOn = true;
    // Muzyka nie miala wlasnej flagi - stan siedzial w mikserze
    // (`music.playing().empty()`), a pole wyboru musi miec co przelaczac.
    bool musicOn = true;

    static const int OPT_TABS = 4;
    static const char *OptTabName(int k)
    {
        static const char *kN[OPT_TABS] = { "GLOWNE", "USTAWIENIA",
                                            "ASYSTENCI", "CELE" };
        return kN[k < 0 || k >= OPT_TABS ? 0 : k];
    }

    // Zapis i wczytanie gry to jedyne pozycje, ktorych remake nie ma.
    static bool OptDead(int k) { return k == 0 || k == 1; }

    bool OptTabRect(const RECT &w, int k, RECT &r)
    {
        if (k < 0 || k >= OPT_TABS) return false;
        RECT b = WinBody(WIN_OPTIONS, w);
        int cw = int(b.right - b.left) / OPT_TABS;
        r.left = b.left + k * cw;
        r.top = b.top + 1;
        r.right = r.left + cw - 2;
        r.bottom = r.top + font.height() + 3;
        return true;
    }

    int OptTabHit(int px, int py)
    {
        RECT w;
        if (winOpen != WIN_OPTIONS || !WinRect(WIN_OPTIONS, w)) return -1;
        for (int k = 0; k < OPT_TABS; ++k) {
            RECT r;
            if (!OptTabRect(w, k, r)) break;
            if (px >= r.left && px < r.right && py >= r.top && py < r.bottom)
                return k;
        }
        return -1;
    }

    void DrawOptTabs(const RECT &w)
    {
        int hov = OptTabHit(mouse.x, mouse.y);
        for (int k = 0; k < OPT_TABS; ++k) {
            RECT r;
            if (!OptTabRect(w, k, r)) break;
            if (k == optTab) { Fill(r, RaceAccent(), 90); Frame(r, RaceAccent()); }
            else if (k == hov) Frame(r, 0xE0E0A0);
            const char *nm = OptTabName(k);
            int tw = 0;
            for (const char *c = nm; *c; ++c) tw += font.charWidth(uint8_t(*c));
            int tx = r.left + (int(r.right - r.left) - tw) / 2;
            if (tx < r.left + 1) tx = r.left + 1;
            TextAt(k == optTab ? fontYellow : font, tx, r.top + 1, nm);
        }
    }

    // Wiersz zakladki. Numeracja wierszy jest ta sama, co przy rysowaniu.
    void OptRow(int row)
    {
        if (optTab == 0) {
            switch (row) {
            case 1: case 2: Say("remake nie ma zapisu gry"); return;
            case 3: OpenTerrain(g_gameDir); Say("mapa od nowa", 2.0f); return;
            case 4: screen = SCR_MENU; winOpen = WIN_NONE; return;
            case 5: quitRequested = true; return;
            case 6: Surrender(); return;
            default: return;
            }
        }
        if (optTab == 1) {
            switch (row) {
            case 1:
                if (music.playing().empty()) StartMusic(0);
                else music.stop();
                return;
            case 2: speedScale = speedScale > 0.4f ? 0.22f : 0.6f; return;
            case 3: shadowsOn = !shadowsOn; return;
            case 4: fogOn = !fogOn; return;
            case 5: terrTextured = !terrTextured; return;
            case 6: terrMeshed = !terrMeshed; return;
            // Pozycji z filtrem obrazu **gra nie ma** - to dodatek remake'u,
            // dostawiony za wierszami, ktore w oryginale tam sa.
            case 7: CycleShader(); return;
            default: return;
            }
        }
        if (optTab == 2 && row == 1) {
            if (!aiOn) { aiOn = true; aiLevel = 0; }
            else if (aiLevel < 2) ++aiLevel;
            else aiOn = false;
        }
    }

    bool quitRequested = false;

    // PODDANIE SIE - napis 16022. Oddajemy wszystko, co nasze; `CheckWin`
    // konczy partie tak samo, jak gdyby nas zniszczono.
    void Surrender()
    {
        for (Unit &u : units) if ((u.owner & 7) == uint32_t(me & 7)) u.hp = 0;
        for (Bld &b : blds)   if ((b.owner & 7) == uint32_t(me & 7)) b.hp = 0;
        Say("poddanie sie", 3.0f);
    }

    void OpenWin(int id)
    {
        // Gra ma na to wlasny dzwiek: `OptPanelTy::SwitchOptPanel` gra 175.
        if (id != WIN_NONE) sfx.play(winOpen == id ? sndev::SFX_CLICK
                                                   : sndev::SFX_PANEL);
        winOpen = winOpen == id ? WIN_NONE : id;
        winPage = 0;
        if (winOpen != WIN_RESEARCH) researchBld = -1;
        if (winOpen == WIN_PAUSE) paused = true;
        else if (id == WIN_PAUSE) paused = false;
    }

    // Gniazdo listy w oknie: prosty rzad kafli 48x33 pod tytulem.
    static const int WIN_COLS = 5, WIN_ROWS = 2;
    bool WinSlot(int id, int k, RECT &r)
    {
        RECT w;
        if (k < 0 || k >= WIN_COLS * WIN_ROWS || !WinRect(id, w)) return false;
        r.left = w.left + 14 + (k % WIN_COLS) * 50;
        r.top = w.top + 34 + (k / WIN_COLS) * 38;
        r.right = r.left + 48;
        r.bottom = r.top + 33;
        return r.bottom <= w.bottom - 6;
    }

